package com.rafat.munasabati;

import android.app.*;import android.content.*;import android.os.Build;import java.util.List;

public class AhlBaytReminderReceiver extends BroadcastReceiver{
 private static final String CH="ahlbayt_occasions_v1";
 @Override public void onReceive(Context c,Intent in){if(!AhlBaytCalendar.remindersEnabled(c))return;int idx=in.getIntExtra("index",-1);List<AhlBaytCalendar.Occasion> all=AhlBaytCalendar.allOccasions();if(idx<0||idx>=all.size())return;AhlBaytCalendar.Occasion o=all.get(idx);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(CH,AppSettings.tr(c,"مناسبات أهل البيت عليهم السلام","Ahl al-Bayt occasions"),NotificationManager.IMPORTANCE_HIGH);ch.enableVibration(true);ch.setDescription(AppSettings.tr(c,"تنبيهات المواليد والوفيات والاستشهادات المدمجة","Built-in birth, death and martyrdom occasion alerts"));nm.createNotificationChannel(ch);}Intent open=new Intent(c,AhlBaytCenterActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,48888,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String title=AhlBaytCalendar.title(c,o);String body=AhlBaytCalendar.kindLabel(c,o);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CH):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(title).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(title+"\n"+body)).setContentIntent(pi).setAutoCancel(true).setPriority(Notification.PRIORITY_HIGH).setDefaults(Notification.DEFAULT_ALL).setVisibility(Notification.VISIBILITY_PUBLIC);nm.notify(48800+idx,b.build());AhlBaytReminderScheduler.schedule(c);}
}
